
data.consultationIntakes??={};
data.consultationCheckins??={};
const hpeConsultDays=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
function hpeConsultWeekOf(){const key=todayKey();return shiftDay(key,-((weekDay(key)+6)%7))}
function hpeConsultDate(value){if(!value)return'—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('pt-BR',{dateStyle:'medium',timeStyle:'short'})}
function hpeConsultIntake(id){return data.consultationIntakes?.[id]||null}
function hpeConsultCheckins(id){const rows=data.consultationCheckins?.[id];return Array.isArray(rows)?rows:[]}
function hpeConsultLatest(id){return hpeConsultCheckins(id).slice().sort((a,b)=>String(b.weekOf||'').localeCompare(String(a.weekOf||'')))[0]||null}
function hpeConsultDateKey(value){if(!value)return'';return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value))}
function hpeConsultWeekCount(id){if(typeof weekCount==='function')return weekCount(id);const start=weekDays()[0];return(data.logs||[]).filter(x=>Number(x.student)===Number(id)&&hpeConsultDateKey(x.date)>=start&&hpeConsultDateKey(x.date)<=todayKey()).length}
function hpeConsultStatus(id){const latest=hpeConsultLatest(id);if(!hpeConsultIntake(id)?.consentAt)return{label:'Ficha inicial pendente',tone:'pending'};if(!latest)return{label:'Primeiro check-in pendente',tone:'pending'};if(latest.weekOf!==hpeConsultWeekOf())return{label:'Check-in desta semana pendente',tone:'pending'};if(latest.reviewedAt)return{label:'Revisado pelo personal',tone:'done'};return{label:'Novo check-in',tone:'new'}}
function hpeConsultStudentPage(){
 const intake=hpeConsultIntake(student),currentCheckin=hpeConsultCheckins(student).find(x=>x.weekOf===hpeConsultWeekOf());
 const weekTarget=goalsFor(student).weekly||3,completed=hpeConsultWeekCount(student);
 const history=hpeConsultCheckins(student).slice().sort((a,b)=>String(b.weekOf||'').localeCompare(String(a.weekOf||''))).slice(0,5);
 return heading('MEU ACOMPANHAMENTO','Consultoria Online','Responda sua ficha inicial e envie um check-in semanal para seu personal.')+
 `<section class="card consult-intro"><div><span class="eyebrow">ACOMPANHAMENTO INDIVIDUAL</span><h2>Seu treino, acompanhado de perto.</h2><p>Atualize suas informações e conte ao personal como está sua rotina. Suas respostas são compartilhadas com o personal vinculado à sua conta.</p></div><div class="consult-shortcuts"><button class="primary" onclick="go('treinos')">Abrir meu treino</button><button onclick="go('interacao')">Conversar com o personal</button></div></section>
 <section class="consult-layout"><div class="card"><div class="row"><div><span class="eyebrow">FICHA INICIAL</span><h2>Como adaptar seu acompanhamento</h2></div><span class="tag">${intake?.updatedAt?'ATUALIZADA':'PREENCHIMENTO'}</span></div>
 <p>Informe seus horários e preferências. Não inclua diagnósticos; descreva apenas adaptações ou movimentos que deseja evitar.</p>
 <form class="consult-form" onsubmit="hpeSaveConsultIntake(event)">
 <fieldset class="consult-fieldset"><legend>Dias em que consegue treinar</legend><div class="consult-days">${hpeConsultDays.map((day,i)=>`<label><input type="checkbox" name="availableDays" value="${i}" ${(intake?.availableDays||[]).includes(i)?'checked':''}>${day}</label>`).join('')}</div></fieldset>
 <label>Tempo disponível por treino<select name="duration"><option value="30" ${intake?.duration==='30'?'selected':''}>Até 30 minutos</option><option value="45" ${!intake?.duration||intake.duration==='45'?'selected':''}>Cerca de 45 minutos</option><option value="60" ${intake?.duration==='60'?'selected':''}>Cerca de 1 hora</option><option value="90" ${intake?.duration==='90'?'selected':''}>Mais de 1 hora</option></select></label>
 <label>Movimentos que prefere adaptar ou evitar (opcional)<textarea name="limitations" rows="3" maxlength="500" placeholder="Ex.: prefiro evitar exercícios ajoelhado">${esc(intake?.limitations||'')}</textarea></label>
 <label>O que mais gostaria que o personal soubesse? (opcional)<textarea name="notes" rows="3" maxlength="500" placeholder="Conte sobre sua rotina ou objetivo">${esc(intake?.notes||'')}</textarea></label>
 <label class="consult-consent"><input type="checkbox" name="consent" value="yes" required ${intake?.consentAt?'checked':''}> Autorizo compartilhar estas respostas com o personal responsável pelo meu acompanhamento.</label>
 <button class="primary">${intake?'Atualizar ficha':'Salvar ficha inicial'}</button></form></div>
 <div class="card"><div class="row"><div><span class="eyebrow">CHECK-IN DA SEMANA</span><h2>Como você está se sentindo?</h2></div><span class="tag">${currentCheckin?'ENVIADO':'PENDENTE'}</span></div>
 <p>Treinos registrados nesta semana: <b>${completed} de ${weekTarget}</b>. Seu check-in ajuda o personal a ajustar o acompanhamento.</p>
 ${!intake?.consentAt?'<div class="empty consult-empty">Salve a ficha inicial e autorize o compartilhamento para enviar o check-in.</div>':`<form class="consult-form" onsubmit="hpeSaveConsultCheckin(event)">
 <label>Nível de energia<select name="energy" required><option value="">Selecione</option>${['Muito baixa','Baixa','Regular','Boa','Muito boa'].map((label,i)=>`<option value="${i+1}" ${Number(currentCheckin?.energy)===i+1?'selected':''}>${i+1} · ${label}</option>`).join('')}</select></label>
 <label>Como está sua recuperação e seu sono?<select name="recovery" required><option value="">Selecione</option>${['Muito ruim','Ruim','Regular','Boa','Muito boa'].map((label,i)=>`<option value="${i+1}" ${Number(currentCheckin?.recovery)===i+1?'selected':''}>${i+1} · ${label}</option>`).join('')}</select></label>
 <label>Algum movimento causou desconforto? (opcional)<textarea name="discomfort" rows="2" maxlength="500" placeholder="Descreva somente o movimento e o que sentiu">${esc(currentCheckin?.discomfort||'')}</textarea></label>
 <label>Comentário ou pedido de ajuste (opcional)<textarea name="notes" rows="3" maxlength="700" placeholder="Como foi sua semana de treino?">${esc(currentCheckin?.notes||'')}</textarea></label>
 <p class="note">O check-in será enviado ao personal vinculado. Você pode atualizar sua resposta durante esta semana.</p>
 <button class="primary">${currentCheckin?'Atualizar check-in':'Enviar check-in semanal'}</button></form>`}
 ${history.length?`<div class="consult-history"><h3>Check-ins anteriores</h3>${history.map(item=>`<article class="consult-history-item"><div><b>Semana de ${esc(item.weekOf||'—')}</b><p>Energia ${Number(item.energy)||'—'}/5 · Recuperação ${Number(item.recovery)||'—'}/5</p></div><span class="consult-status ${item.reviewedAt?'done':'new'}">${item.reviewedAt?'Revisado':'Aguardando leitura'}</span></article>`).join('')}</div>`:''}
 </div></section>`
}
function hpeConsultCoachPage(){
 const students=visibleStudents(),intake=hpeConsultIntake(student),latest=hpeConsultLatest(student);
 const measurements=(data.measurements||[]).filter(x=>Number(x.student)===Number(student)).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 const history=hpeConsultCheckins(student).slice().sort((a,b)=>String(b.weekOf||'').localeCompare(String(a.weekOf||''))).slice(0,6);
 const status=hpeConsultStatus(student);
 return heading('CONSULTORIA ONLINE',`Acompanhamento de ${esc(current().name)}`,'Ficha inicial, check-ins e evolução do aluno em um só lugar.',studentSelector())+
 `<div class="grid stats consult-stats"><section class="card stat"><p>Treinos registrados nesta semana</p><strong>${hpeConsultWeekCount(student)} <small>/ ${goalsFor(student).weekly||3}</small></strong><small>Registros de treino e atendimentos</small></section><section class="card stat"><p>Check-in mais recente</p><strong class="consult-stat-date">${latest?esc(latest.weekOf):'—'}</strong><small>${latest?'Energia '+Number(latest.energy)+'/5 · recuperação '+Number(latest.recovery)+'/5':'Aguardando resposta do aluno'}</small></section><section class="card stat"><p>Última medida registrada</p><strong class="consult-stat-date">${measurements[0]?.weight?esc(measurements[0].weight)+' kg':'—'}</strong><small>${measurements[0]?.date?esc(hpeConsultDate(measurements[0].date)):'Acompanhe na aba Evolução'}</small></section></div>
 <section class="consult-layout"><div class="card"><div class="row"><div><span class="eyebrow">FICHA DO ALUNO</span><h2>${esc(current().name)}</h2></div><span class="consult-status ${status.tone}">${status.label}</span></div>
 <div class="consult-facts"><div><small>Objetivo</small><b>${esc(current().goal||'Não informado')}</b></div><div><small>Nível</small><b>${esc(current().level||'Não informado')}</b></div><div><small>Dias disponíveis</small><b>${intake?.availableDays?.length?intake.availableDays.map(i=>hpeConsultDays[i]).filter(Boolean).join(', '):'Aguardando ficha'}</b></div><div><small>Tempo por treino</small><b>${intake?.duration?esc(intake.duration)+' min':'Aguardando ficha'}</b></div></div>
 ${intake?.limitations?`<div class="consult-answer"><small>Movimentos a adaptar ou evitar</small><p>${esc(intake.limitations)}</p></div>`:''}${intake?.notes?`<div class="consult-answer"><small>Observações do aluno</small><p>${esc(intake.notes)}</p></div>`:''}
 <p class="note">${intake?.updatedAt?'Ficha atualizada em '+esc(hpeConsultDate(intake.updatedAt)):'Peça ao aluno para preencher a ficha na área “Meu acompanhamento”.'}</p>
 <div class="consult-shortcuts"><button class="primary" onclick="go('treinos')">Editar treino</button><button onclick="go('evolucao')">Ver evolução</button><button onclick="go('interacao')">Conversar</button></div></div>
 <div class="card"><div class="row"><div><span class="eyebrow">CHECK-IN</span><h2>Retorno do aluno</h2></div>${latest?'<span class="tag">SEMANA '+esc(latest.weekOf||'')+'</span>':'<span class="tag">AGUARDANDO</span>'}</div>
 ${latest?`<div class="consult-checkin-summary"><div><small>Energia</small><b>${Number(latest.energy)||'—'} / 5</b></div><div><small>Recuperação</small><b>${Number(latest.recovery)||'—'} / 5</b></div></div>${latest.discomfort?`<div class="consult-answer"><small>Desconforto informado</small><p>${esc(latest.discomfort)}</p></div>`:''}${latest.notes?`<div class="consult-answer"><small>Comentário do aluno</small><p>${esc(latest.notes)}</p></div>`:''}<p class="note">Enviado em ${esc(hpeConsultDate(latest.updatedAt||latest.createdAt))}</p>${latest.reviewedAt?'<span class="consult-status done">✓ Revisado em '+esc(hpeConsultDate(latest.reviewedAt))+'</span>':hpeProfile?.role==='personal'?`<button class="primary" onclick="hpeReviewConsultCheckin(${Number(student)},'${esc(latest.weekOf)}')">Marcar check-in como revisado</button>`:''}`:'<div class="empty consult-empty">O check-in semanal aparecerá aqui quando o aluno enviar.</div>'}
 ${history.length?`<div class="consult-history"><h3>Histórico recente</h3>${history.map(item=>`<article class="consult-history-item"><div><b>Semana de ${esc(item.weekOf||'—')}</b><p>Energia ${Number(item.energy)||'—'}/5 · Recuperação ${Number(item.recovery)||'—'}/5</p></div><span class="consult-status ${item.reviewedAt?'done':'new'}">${item.reviewedAt?'Revisado':'Novo'}</span></article>`).join('')}</div>`:''}
 </div></section>
 <section class="card consult-evolution"><div class="row"><div><span class="eyebrow">EVOLUÇÃO</span><h2>Medidas e consistência</h2></div><button onclick="go('evolucao')">Abrir histórico completo</button></div>${chart()}<p class="note">Os registros de peso são opcionais e ficam visíveis para o aluno e o personal vinculado.</p></section>
 <section class="card consult-roster"><div class="row"><div><span class="eyebrow">ALUNOS</span><h2>Sua carteira de consultoria</h2></div><span class="tag">${students.length} ALUNOS</span></div>
 ${students.length?'<div class="consult-roster-list">'+students.map(s=>{const item=hpeConsultStatus(s.id);return `<article class="consult-roster-item"><div><b>${esc(s.name)}</b><p>${esc(s.goal||'Objetivo não informado')} · ${weekCount(s.id)} treino(s) nesta semana</p></div><span class="consult-status ${item.tone}">${item.label}</span><button onclick="selectStudent(${Number(s.id)});go('consultoria')">Acompanhar</button></article>`}).join('')+'</div>':'<div class="empty">Cadastre ou vincule um aluno para iniciar a consultoria.</div>'}
 </section>`
}
window.hpeSaveConsultIntake=event=>{event.preventDefault();if(role!=='aluno')return;const form=new FormData(event.currentTarget),availableDays=form.getAll('availableDays').map(Number).filter(i=>i>=0&&i<7);if(!availableDays.length){toast('Selecione pelo menos um dia disponível.');return}if(form.get('consent')!=='yes'){toast('Autorize o compartilhamento com seu personal para salvar.');return}const prior=hpeConsultIntake(student),now=new Date().toISOString();data.consultationIntakes[student]={availableDays,duration:String(form.get('duration')||'45'),limitations:String(form.get('limitations')||'').trim().slice(0,500),notes:String(form.get('notes')||'').trim().slice(0,500),consentAt:prior?.consentAt||now,updatedAt:now};save();render();toast('Ficha inicial salva e compartilhada com seu personal.')}
window.hpeSaveConsultCheckin=event=>{event.preventDefault();if(role!=='aluno'||!hpeConsultIntake(student)?.consentAt){toast('Preencha a ficha inicial antes do check-in.');return}const form=new FormData(event.currentTarget),energy=Number(form.get('energy')),recovery=Number(form.get('recovery'));if(energy<1||energy>5||recovery<1||recovery>5){toast('Informe energia e recuperação.');return}const weekOf=hpeConsultWeekOf(),now=new Date().toISOString(),rows=hpeConsultCheckins(student),index=rows.findIndex(x=>x.weekOf===weekOf),prior=index>=0?rows[index]:null,item={weekOf,energy,recovery,discomfort:String(form.get('discomfort')||'').trim().slice(0,500),notes:String(form.get('notes')||'').trim().slice(0,700),updatedAt:now,createdAt:prior?.createdAt||now,reviewedAt:null};if(index>=0)rows[index]=item;else rows.push(item);data.consultationCheckins[student]=rows;save();render();toast('Check-in semanal enviado ao seu personal.')}
window.hpeReviewConsultCheckin=(id,weekOf)=>{if(hpeProfile?.role!=='personal')return;const item=hpeConsultCheckins(id).find(x=>x.weekOf===weekOf);if(!item)return;item.reviewedAt=new Date().toISOString();save();render();toast('Check-in marcado como revisado.')}
const hpeConsultBaseRender=render;
render=function(){hpeConsultBaseRender();if(document.body.classList.contains('signed-out'))return;const nav=$('#nav');if(role==='personal'&&!nav.querySelector('[data-consult-nav]'))nav.insertAdjacentHTML('beforeend',`<button data-consult-nav class="${page==='consultoria'?'active':''}" onclick="go('consultoria')">◉ &nbsp; Consultoria Online</button>`);if(role==='aluno'&&!nav.querySelector('[data-consult-nav]'))nav.insertAdjacentHTML('beforeend',`<button data-consult-nav class="${page==='consultoria'?'active':''}" onclick="go('consultoria')">◉ &nbsp; Meu acompanhamento</button>`);if(page==='consultoria')$('#content').innerHTML=role==='personal'?hpeConsultCoachPage():role==='aluno'?hpeConsultStudentPage():'<section class="card"><p>Esta área está disponível para aluno e personal.</p></section>'}
